from collections import deque

def comps(grid, bg=8, exclude_frame=True):
    H,W=grid.shape
    seen=set(); cs=[]
    for r in range(H):
      for c in range(W):
        if grid[r,c]==bg or (r,c) in seen: continue
        q=[(r,c)];seen.add((r,c));cells=[]
        for x,y in q:
          cells.append((x,y))
          for p in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            a,b=p
            if 0<=a<H and 0<=b<W and grid[a,b]!=bg and p not in seen:
              seen.add(p);q.append(p)
        cs.append(cells)
    return cs

